def reverse_k_chars(s, k):
    # Convert the string to a list for easier manipulation
    chars = list(s)
    n = len(chars)
    # If k is greater than the length of the string, reverse the entire string
    if k > n:
        k = n
    # Reverse the first k characters
    for i in range(k // 2):
        chars[i], chars[k - i - 1] = chars[k - i - 1], chars[i]
    # Join the list back into a string and return it
    return ''.join(chars)

def decode_string(s: str) -> str:
    stack = []
    current_string = ""
    current_number = 0

    for char in s:
        if char.isdigit():
            current_number = current_number * 10 + int(char)
        elif char == '[':
            # Push the current state onto the stack
            stack.append((current_string, current_number))
            # Reset current string and number for the new segment
            current_string = ""
            current_number = 0
        elif char == ']':
            # Pop the last state from the stack
            prev_string, num = stack.pop()
            # Update the current string with the decoded segment
            current_string = prev_string + num * current_string
        else:
            # Append the character to the current string
            current_string += char

    return current_string

